MATCH (v:PlantItem {tag: 'V-9701'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem {tag: 'V-30301'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'K-10701'}), (b:PlantItem {tag: 'R-10601'})
RETURN EXISTS { (a)-[:line_to*1..]->(b) } AS reachable,
       EXISTS {
         MATCH (a)-[:line_to]->(n:PlantItem)
         WHERE n.tag <> 'E-10601'
           AND EXISTS { (n)-[:line_to*0..]->(b) }
       } AS reachable_without_E

MATCH (e:PlantItem {tag: 'E-25201'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem {tag: 'V-30301'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;
